import{_ as t,o,c as n,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"UC 05 — AI Features (UC-088 – UC-106)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/05-ai-features.md","filePath":"ba/use-cases/05-ai-features.md"}'),a={name:"ba/use-cases/05-ai-features.md"};function d(r,e,l,i,s,g){return o(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="uc-05-—-ai-features-uc-088-–-uc-106" tabindex="-1">UC 05 — AI Features (<code>UC-088</code> – <code>UC-106</code>) <a class="header-anchor" href="#uc-05-—-ai-features-uc-088-–-uc-106" aria-label="Permalink to &quot;UC 05 — AI Features (`UC-088` – `UC-106`)&quot;">​</a></h1><p>&gt; <a href="./04-content-task-workflow.html">&lt;&lt; 04-content-task-workflow.md</a> | <a href="./README.html">UC Index</a> | <a href="./../06-ai-features.html">Domain BA Spec: 06-ai-features.md</a> | <a href="./06-publishing-social.html">06-publishing-social.md &gt;&gt;</a> &gt; &gt; Đồng bộ chuẩn xác 1-đối-1 với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code> và <code>AGENTS.md</code>. Chỉ sử dụng <strong>6 Vai trò Hệ thống Chuẩn (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>.</p><hr><h2 id="_1-bang-tong-hop-use-cases-19-ucs" tabindex="-1">1. Bảng Tổng Hợp Use Cases (19 UCs) <a class="header-anchor" href="#_1-bang-tong-hop-use-cases-19-ucs" aria-label="Permalink to &quot;1. Bảng Tổng Hợp Use Cases (19 UCs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">UC ID</th><th style="text-align:left;">Use Case Title</th><th style="text-align:left;">Canonical Actor(s)</th><th style="text-align:center;">Related FR</th><th style="text-align:left;">Business Rules</th></tr></thead><tbody><tr><td style="text-align:center;"><code>UC-088</code></td><td style="text-align:left;">View Trending Topics Suggestions</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.1</code></td><td style="text-align:left;"><code>BR-45</code></td></tr><tr><td style="text-align:center;"><code>UC-089</code></td><td style="text-align:left;">View AI Trend Knowledge Graph</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Admin</code></td><td style="text-align:center;"><code>3.7.2</code></td><td style="text-align:left;"><code>BR-45</code></td></tr><tr><td style="text-align:center;"><code>UC-090</code></td><td style="text-align:left;">View Brand Knowledge Documents</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;"><code>3.7.3</code></td><td style="text-align:left;"><code>BR-20, BR-46</code></td></tr><tr><td style="text-align:center;"><code>UC-091</code></td><td style="text-align:left;">Upload Brand Knowledge Document</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.7.4</code></td><td style="text-align:left;"><code>BR-20, BR-46, BR-49</code></td></tr><tr><td style="text-align:center;"><code>UC-092</code></td><td style="text-align:left;">Delete Brand Knowledge Document</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;"><code>3.7.5</code></td><td style="text-align:left;"><code>BR-20, BR-47</code></td></tr><tr><td style="text-align:center;"><code>UC-093</code></td><td style="text-align:left;">Generate Caption</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.6</code></td><td style="text-align:left;"><code>BR-46, BR-48, BR-49, BR-60, BR-64</code></td></tr><tr><td style="text-align:center;"><code>UC-094</code></td><td style="text-align:left;">Generate Ambassador</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.7</code></td><td style="text-align:left;"><code>BR-46, BR-48, BR-49, BR-60, BR-64</code></td></tr><tr><td style="text-align:center;"><code>UC-095</code></td><td style="text-align:left;">View Image Style Template</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.8</code></td><td style="text-align:left;"><code>BR-46, BR-49</code></td></tr><tr><td style="text-align:center;"><code>UC-096</code></td><td style="text-align:left;">Generate Image</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.9</code></td><td style="text-align:left;"><code>BR-46, BR-48, BR-49, BR-50, BR-60, BR-64</code></td></tr><tr><td style="text-align:center;"><code>UC-097</code></td><td style="text-align:left;">View Video Style Template</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.10</code></td><td style="text-align:left;"><code>BR-46, BR-49</code></td></tr><tr><td style="text-align:center;"><code>UC-098</code></td><td style="text-align:left;">Generate Video</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.11</code></td><td style="text-align:left;"><code>BR-46, BR-48, BR-49, BR-50, BR-60, BR-64</code></td></tr><tr><td style="text-align:center;"><code>UC-099</code></td><td style="text-align:left;">Export File</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.12</code></td><td style="text-align:left;"><code>BR-20, BR-50</code></td></tr><tr><td style="text-align:center;"><code>UC-100</code></td><td style="text-align:left;">Crawl Schedule Config</td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;"><code>3.7.13</code></td><td style="text-align:left;"><code>BR-45, BR-62, BR-65</code></td></tr><tr><td style="text-align:center;"><code>UC-101</code></td><td style="text-align:left;">Suggest Hashtag Trend</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><code>3.7.14</code></td><td style="text-align:left;"><code>BR-39, BR-45</code></td></tr><tr><td style="text-align:center;"><code>UC-102</code></td><td style="text-align:left;">View Collaborator Directory</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.7.15</code></td><td style="text-align:left;"><code>BR-20, BR-51</code></td></tr><tr><td style="text-align:center;"><code>UC-103</code></td><td style="text-align:left;">Create Collaborator Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.7.16</code></td><td style="text-align:left;"><code>BR-15, BR-51</code></td></tr><tr><td style="text-align:center;"><code>UC-104</code></td><td style="text-align:left;">Update Collaborator Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.7.17</code></td><td style="text-align:left;"><code>BR-51</code></td></tr><tr><td style="text-align:center;"><code>UC-105</code></td><td style="text-align:left;">Remove Collaborator Profile</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.7.18</code></td><td style="text-align:left;"><code>BR-15, BR-51</code></td></tr><tr><td style="text-align:center;"><code>UC-106</code></td><td style="text-align:left;">Recommend Collaborator</td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;"><code>3.7.19</code></td><td style="text-align:left;"><code>BR-51, BR-52</code></td></tr></tbody></table><hr><h2 id="uc-088-—-view-trending-topics-suggestions" tabindex="-1">UC-088 — View Trending Topics Suggestions <a class="header-anchor" href="#uc-088-—-view-trending-topics-suggestions" aria-label="Permalink to &quot;UC-088 — View Trending Topics Suggestions&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.1</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-45</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem bảng điều khiển gợi ý các chủ đề và từ khóa xu hướng đang thịnh hành (View Trending Topics Suggestions — /workspaces/:id/ai/trends). Hệ thống thu thập dữ liệu thị trường Việt Nam, tính điểm bùng nổ xu hướng thông qua thuật toán phát hiện bất thường BM25 kết hợp xếp hạng đồ thị Neo4j (Personalized PageRank &amp; Betweenness Centrality) để gợi ý các chủ đề viral phù hợp với ngành hàng của Workspace (BR-45).</li></ul><hr><h2 id="uc-089-—-view-ai-trend-knowledge-graph" tabindex="-1">UC-089 — View AI Trend Knowledge Graph <a class="header-anchor" href="#uc-089-—-view-ai-trend-knowledge-graph" aria-label="Permalink to &quot;UC-089 — View AI Trend Knowledge Graph&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.2</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-45</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Khám phá trực quan Đồ thị Tri thức Xu hướng (View AI Trend Knowledge Graph — /workspaces/:id/ai/trends/graph). Hiển thị mạng lưới các nút (Từ khóa, Chủ đề, Thực thể, Hashtag) và các cạnh liên kết đồng xuất hiện trong cơ sở dữ liệu đồ thị Neo4j, giúp người làm nội dung nắm bắt ngữ cảnh lan truyền của từng xu hướng (BR-45).</li></ul><hr><h2 id="uc-090-—-view-brand-knowledge-documents" tabindex="-1">UC-090 — View Brand Knowledge Documents <a class="header-anchor" href="#uc-090-—-view-brand-knowledge-documents" aria-label="Permalink to &quot;UC-090 — View Brand Knowledge Documents&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.3</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-46</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem danh sách và tìm kiếm ngữ nghĩa các tài liệu Brand Guideline trong kho tri thức AI của Workspace (View Brand Knowledge Documents — /workspaces/:id/ai/knowledge). Hiển thị trạng thái vector hóa (PENDING, INDEXED, FAILED), số lượng đoạn văn bản (chunks) đã nhúng trong ChromaDB và cho phép kiểm tra truy vấn ngữ nghĩa theo từng Workspace độc lập (BR-20, BR-46).</li></ul><hr><h2 id="uc-091-—-upload-brand-knowledge-document" tabindex="-1">UC-091 — Upload Brand Knowledge Document <a class="header-anchor" href="#uc-091-—-upload-brand-knowledge-document" aria-label="Permalink to &quot;UC-091 — Upload Brand Knowledge Document&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.4</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-46, BR-49</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG22, MSG46</code></li><li><strong>Specification &amp; Flow:</strong> Tải lên tài liệu Brand Guideline (định dạng PDF, DOCX, TXT, HTML, tối đa 10 MB (hoặc Web URL)) vào kho tri thức RAG của Workspace (Upload Brand Knowledge Document — /workspaces/:id/ai/knowledge). Hệ thống quét bảo mật tệp (magic-byte &amp; macro), lưu bản gốc lên S3, tự động băm nhỏ văn bản (chunking) và tạo vector nhúng lưu vào phân vùng ChromaDB riêng biệt của Workspace để làm ngữ cảnh chuẩn khi AI sinh nội dung (BR-20, BR-46).</li></ul><hr><h2 id="uc-092-—-delete-brand-knowledge-document" tabindex="-1">UC-092 — Delete Brand Knowledge Document <a class="header-anchor" href="#uc-092-—-delete-brand-knowledge-document" aria-label="Permalink to &quot;UC-092 — Delete Brand Knowledge Document&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.5</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Client</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-47</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG46</code></li><li><strong>Specification &amp; Flow:</strong> Xóa tài liệu Brand Guideline khỏi kho tri thức AI của Workspace (Delete Brand Knowledge Document — /workspaces/:id/ai/knowledge/:docId). Hệ thống xóa tệp tài liệu trên S3 đồng thời xóa sạch toàn bộ các đoạn vector nhúng (embeddings) tương ứng trong ChromaDB để AI không còn truy xuất dữ liệu cũ (BR-20, BR-47).</li></ul><hr><h2 id="uc-093-—-generate-caption" tabindex="-1">UC-093 — Generate Caption <a class="header-anchor" href="#uc-093-—-generate-caption" aria-label="Permalink to &quot;UC-093 — Generate Caption&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.6</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-46, BR-48, BR-49, BR-60, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG47, MSG48, MSG49</code></li><li><strong>Specification &amp; Flow:</strong> Sinh tự động nội dung bài viết / caption mạng xã hội bằng mô hình ngôn ngữ lớn kết hợp kho tri thức thương hiệu (Generate Caption — /workspaces/:id/ai/caption). Sử dụng kiến trúc Brand Hybrid GraphRAG (truy xuất ngữ cảnh thương hiệu từ ChromaDB + xu hướng từ Neo4j) đưa vào LLM (Groq Llama / Gemini) để tạo caption chuẩn giọng điệu thương hiệu theo từng nền tảng; kiểm tra và khấu trừ AI Credit nguyên tử (atomic) theo bảng giá hiện hành, tự động hoàn trả credit nếu tiến trình AI gặp lỗi (BR-49, BR-48).</li></ul><hr><h2 id="uc-094-—-generate-ambassador" tabindex="-1">UC-094 — Generate Ambassador <a class="header-anchor" href="#uc-094-—-generate-ambassador" aria-label="Permalink to &quot;UC-094 — Generate Ambassador&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.7</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-46, BR-48, BR-49, BR-60, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG47, MSG48, MSG49</code></li><li><strong>Specification &amp; Flow:</strong> Khởi tạo hình mẫu Đại sứ Thương hiệu Ảo bằng AI (Generate Ambassador — /workspaces/:id/ai/ambassadors). Cho phép tạo và lưu trữ các nhân vật/người mẫu ảo đại diện nhất quán cho thương hiệu (dựa trên ảnh chân dung tham chiếu kết hợp mô tả ngoại hình, độ tuổi, phong cách bằng pipeline Qwen Image 2.1 LoRA) để tái sử dụng xuyên suốt khi sinh hình ảnh sản phẩm (3.7.9) và video ngắn (3.7.11) khi nhãn hàng chưa có người mẫu riêng (BR-49, BR-48).</li></ul><hr><h2 id="uc-095-—-view-image-style-template" tabindex="-1">UC-095 — View Image Style Template <a class="header-anchor" href="#uc-095-—-view-image-style-template" aria-label="Permalink to &quot;UC-095 — View Image Style Template&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.8</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-46, BR-49</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem thư viện các mẫu phong cách hình ảnh thiết lập sẵn (View Image Style Template — /workspaces/:id/ai/image-styles). Hệ thống cung cấp các Style Preset mẫu (như Studio Product, Anime, Mùa xuân, Hồi ức Vintage, Cyberpunk, Minimalist Editorial...) kèm ảnh minh họa và thông số kỹ thuật ẩn để người dùng chọn nhanh phong cách mà không cần viết câu lệnh (prompt) phức tạp (BR-49).</li></ul><hr><h2 id="uc-096-—-generate-image" tabindex="-1">UC-096 — Generate Image <a class="header-anchor" href="#uc-096-—-generate-image" aria-label="Permalink to &quot;UC-096 — Generate Image&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.9</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-46, BR-48, BR-49, BR-50, BR-60, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG47, MSG48, MSG49</code></li><li><strong>Specification &amp; Flow:</strong> Sinh hình ảnh quảng cáo/bài đăng bằng AI (Generate Image — /workspaces/:id/ai/image). Tổng hợp dữ liệu đầu vào từ biểu mẫu mô tả + Mẫu phong cách (3.7.8) + Đại sứ ảo (3.7.7) + Tư liệu sản phẩm trong kho để tạo câu lệnh hoàn chỉnh đưa vào mô hình khuếch tán tích hợp LoRA (Qwen Image 2.1 (ComfyUI GPU)); kiểm tra hạn mức, khấu trừ AI Credit nguyên tử và lưu ảnh kết quả vào kho tư liệu (BR-49, BR-48).</li></ul><hr><h2 id="uc-097-—-view-video-style-template" tabindex="-1">UC-097 — View Video Style Template <a class="header-anchor" href="#uc-097-—-view-video-style-template" aria-label="Permalink to &quot;UC-097 — View Video Style Template&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.10</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-46, BR-49</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem thư viện các mẫu phong cách và chuyển động máy quay cho Video AI (View Video Style Template — /workspaces/:id/ai/video-styles). Tương tự thư viện mẫu ảnh (3.7.8) nhưng chuyên biệt cho sinh video ngắn: cung cấp các mẫu chuyển động camera (Pan, Zoom, Orbit, Cinematic Slow-mo), ánh sáng và nhịp điệu hình ảnh cho Reels/TikTok/Shorts (BR-49).</li></ul><hr><h2 id="uc-098-—-generate-video" tabindex="-1">UC-098 — Generate Video <a class="header-anchor" href="#uc-098-—-generate-video" aria-label="Permalink to &quot;UC-098 — Generate Video&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.11</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-46, BR-48, BR-49, BR-50, BR-60, BR-64</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG47, MSG48, MSG49</code></li><li><strong>Specification &amp; Flow:</strong> Sinh video ngắn phục vụ đăng tải mạng xã hội bằng AI (Generate Video — /workspaces/:id/ai/video). Kết hợp câu lệnh mô tả kịch bản cảnh quay, hình ảnh tham chiếu / Đại sứ thương hiệu ảo (3.7.7) và Mẫu phong cách video (3.7.10) thông qua API sinh video chuyên dụng (Google Veo / Google Veo 3.1); xử lý bất đồng bộ qua hàng đợi, khấu trừ AI Credit theo thời lượng/độ phân giải và tự động hoàn trả credit nếu tiến trình render thất bại (BR-49, BR-48).</li></ul><hr><h2 id="uc-099-—-export-file" tabindex="-1">UC-099 — Export File <a class="header-anchor" href="#uc-099-—-export-file" aria-label="Permalink to &quot;UC-099 — Export File&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.12</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-50</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG22</code></li><li><strong>Specification &amp; Flow:</strong> Xuất và chuyển đổi định dạng tệp đa phương tiện do AI khởi tạo về máy cá nhân (Export File — /workspaces/:id/ai/export). Khác với tải xuống tư liệu gốc đơn thuần (3.6.19), chức năng Export cho phép người dùng lựa chọn xuất ra nhiều định dạng chuẩn tối ưu cho từng mạng xã hội (Video: MP4 H.264, WebM; Ảnh: PNG, JPG, WEBP) và tỷ lệ khung hình (9:16, 1:1, 16:9) mà không tốn thêm AI Credit (BR-50, BR-50).</li></ul><hr><h2 id="uc-100-—-crawl-schedule-config" tabindex="-1">UC-100 — Crawl Schedule Config <a class="header-anchor" href="#uc-100-—-crawl-schedule-config" aria-label="Permalink to &quot;UC-100 — Crawl Schedule Config&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.13</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Admin</code></li><li><strong>Business Rules:</strong> <code>BR-45, BR-62, BR-65</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG07, MSG60</code></li><li><strong>Specification &amp; Flow:</strong> Cấu hình lịch trình và nguồn thu thập dữ liệu tự động cho bộ cào xu hướng (Crawl Schedule Config — /admin/crawler-config). Thiết lập biểu thức thời gian chạy định kỳ (Cron schedule), danh sách trang/nguồn dữ liệu mục tiêu, lĩnh vực từ khóa, và giới hạn số lượng bài thu thập mỗi phiên cho tiến trình ngầm AI Trend Crawler (BR-45).</li></ul><hr><h2 id="uc-101-—-suggest-hashtag-trend" tabindex="-1">UC-101 — Suggest Hashtag Trend <a class="header-anchor" href="#uc-101-—-suggest-hashtag-trend" aria-label="Permalink to &quot;UC-101 — Suggest Hashtag Trend&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.14</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code>, <code>Creator</code></li><li><strong>Business Rules:</strong> <code>BR-39, BR-45</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG07, MSG47, MSG49</code></li><li><strong>Specification &amp; Flow:</strong> Gợi ý tự động bộ thẻ Hashtag đang thịnh hành bằng AI (Suggest Hashtag Trend — /workspaces/:id/ai/hashtags). Hoạt động tại 2 vị trí: (1) Gợi ý trực tiếp trong trình soạn thảo nội dung (3.6.10) dựa trên nội dung bài viết đang viết, và (2) Gợi ý khi quản lý bộ sưu tập Hashtag của Workspace (3.6.22) để các thành viên thêm nhanh các hashtag có điểm xu hướng cao (BR-45, BR-45).</li></ul><hr><h2 id="uc-102-—-view-collaborator-directory" tabindex="-1">UC-102 — View Collaborator Directory <a class="header-anchor" href="#uc-102-—-view-collaborator-directory" aria-label="Permalink to &quot;UC-102 — View Collaborator Directory&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.15</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-20, BR-51</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07</code></li><li><strong>Specification &amp; Flow:</strong> Xem và lọc danh bạ đối tác truyền thông bên thứ ba của Agency (View Collaborator Directory — /workspaces/:id/collaborators). Quản lý tập trung danh sách KOL, KOC, Báo điện tử, Mạng lưới đặt Banner quảng cáo và Kênh truyền hình TV kèm theo lĩnh vực, bảng giá tham khảo, chỉ số tiếp cận và trạng thái hợp tác trong chiến dịch (BR-51).</li></ul><hr><h2 id="uc-103-—-create-collaborator-profile" tabindex="-1">UC-103 — Create Collaborator Profile <a class="header-anchor" href="#uc-103-—-create-collaborator-profile" aria-label="Permalink to &quot;UC-103 — Create Collaborator Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.16</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-51</code></li><li><strong>System Messages:</strong> <code>MSG02, MSG03, MSG04, MSG07, MSG50</code></li><li><strong>Specification &amp; Flow:</strong> Thêm mới hồ sơ đối tác truyền thông bên thứ ba (KOL/KOC, Báo điện tử, Trang treo Banner, Kênh TV) vào danh bạ của Agency (Create Collaborator Profile — /workspaces/:id/collaborators/new). Lưu trữ Tên đối tác, Phân loại kênh, Lĩnh vực chuyên môn, Quy mô độc giả/người theo dõi, Đơn giá dự kiến và Thông tin liên hệ đầu mối (BR-51).</li></ul><hr><h2 id="uc-104-—-update-collaborator-profile" tabindex="-1">UC-104 — Update Collaborator Profile <a class="header-anchor" href="#uc-104-—-update-collaborator-profile" aria-label="Permalink to &quot;UC-104 — Update Collaborator Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.17</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-51</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG50</code></li><li><strong>Specification &amp; Flow:</strong> Cập nhật thông tin hồ sơ đối tác truyền thông và tiến độ hợp tác trong chiến dịch (Update Collaborator Profile — /workspaces/:id/collaborators/:collaboratorId). Theo dõi trạng thái làm việc thực tế (CONTACTED -&gt; NEGOTIATING -&gt; CONFIRMED -&gt; LIVE_ON_AIR -&gt; COMPLETED), chi phí thực tế và đường dẫn nghiệm thu bài đăng/quảng cáo (Proof of Performance) (BR-51).</li></ul><hr><h2 id="uc-105-—-remove-collaborator-profile" tabindex="-1">UC-105 — Remove Collaborator Profile <a class="header-anchor" href="#uc-105-—-remove-collaborator-profile" aria-label="Permalink to &quot;UC-105 — Remove Collaborator Profile&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.18</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-15, BR-51</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG03, MSG07, MSG36, MSG50</code></li><li><strong>Specification &amp; Flow:</strong> Xóa mềm hoặc ngừng kích hoạt hồ sơ đối tác truyền thông khỏi danh bạ hoạt động của Agency (Remove Collaborator Profile — /workspaces/:id/collaborators/:collaboratorId). Bảo toàn lịch sử chi phí và dữ liệu nghiệm thu của đối tác trong các chiến dịch đã thực hiện trước đó (BR-51).</li></ul><hr><h2 id="uc-106-—-recommend-collaborator" tabindex="-1">UC-106 — Recommend Collaborator <a class="header-anchor" href="#uc-106-—-recommend-collaborator" aria-label="Permalink to &quot;UC-106 — Recommend Collaborator&quot;">​</a></h2><ul><li><strong>Related FR:</strong> <code>3.7.19</code> (3.7 AI Features)</li><li><strong>Canonical Actor(s):</strong> <code>Owner</code>, <code>Manager</code></li><li><strong>Business Rules:</strong> <code>BR-51, BR-52</code></li><li><strong>System Messages:</strong> <code>MSG01, MSG02, MSG07, MSG50</code></li><li><strong>Specification &amp; Flow:</strong> Đề xuất thông minh danh sách đối tác truyền thông bên thứ ba phù hợp bằng AI (Recommend Collaborator — /workspaces/:id/ai/collaborator-recommendations). Dựa trên mục tiêu chiến dịch, ngành hàng thương hiệu và ngân sách dự kiến, AI chấm điểm độ tương thích và phân cấp các phương án tối ưu (Báo điện tử, Trang chạy Banner, Kênh truyền hình TV, KOL/KOC) để Agency và Client lựa chọn (BR-52).</li></ul>',62)])])}const m=t(a,[["render",d]]);export{u as __pageData,m as default};
